 const {t,byId,editMode,openEditor,simpleMode}=useCatalog();const game=byId[e.gameId],EntryBody=editMode?'div':'button';const state=e.pickupArchive?(pickupPeriod(e,now)==='past'?'ended':pickupPeriod(e,now)==='current'?'active':pickupPeriod(e,now)==='upcoming'?'upcoming':'notice'):entryState(e,now);const Icon=kindIcons[e.kind];
 const [failedImage,setFailedImage]=useState('');const image=artworkForLocale(e,locale,'preview',serviceArtworkLocale(e.region,e.gameId)).image;
 const highlights=(e.highlights||[]).map(h=>cleanPublicInformationText(h[locale])).filter(text=>text.trim()),snippets=highlights.length?highlights:e.kind==='package'?(e.contents||[]).map(c=>cleanPublicInformationText(c[locale])).filter(text=>text.trim()):[];
